/**
 * Portfolio Sync by OpenCode — Figma plugin (self-contained bundle).
 * Generated by scripts/figma-sync.mjs — do not edit by hand.
 * Draws PS:<name> frames on the current page from the embedded SPECS.
 * Re-running replaces existing PS:* frames.
 */

const SPECS = __SPECS__;

const FONT_CACHE = {};

async function ensureFont(family, weight) {
  const key = `${family}:${weight}`;
  if (FONT_CACHE[key]) return FONT_CACHE[key];
  const style = weight >= 700 ? "Bold" : weight >= 600 ? "SemiBold" : weight >= 500 ? "Medium" : "Regular";
  const candidates = [
    { family, style },
    { family: "Space Grotesk", style },
    { family: "Inter", style },
  ].filter((f, i, arr) => arr.findIndex((x) => x.family === f.family && x.style === f.style) === i);
  let lastErr = null;
  for (const fontName of candidates) {
    try {
      await figma.loadFontAsync(fontName);
      FONT_CACHE[key] = fontName;
      return fontName;
    } catch (err) {
      lastErr = err;
    }
  }
  console.warn(`⚠️ font no cargada "${family} ${style}": ${lastErr && lastErr.message}`);
  return candidates[candidates.length - 1];
}

function hexToRGB(hex, alpha = 1) {
  const clean = hex.replace("#", "");
  const r = parseInt(clean.slice(0, 2), 16) / 255;
  const g = parseInt(clean.slice(2, 4), 16) / 255;
  const b = parseInt(clean.slice(4, 6), 16) / 255;
  return { r, g, b, a: alpha };
}

function base64ToBytes(b64) {
  try {
    return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  } catch (e) {
    return null;
  }
}

function paint(color) {
  if (typeof color === "string") return { type: "SOLID", color: hexToRGB(color) };
  return { type: "SOLID", color: hexToRGB(color.value, color.a) };
}

function applyFills(node, spec) {
  if (spec.fill) node.fills = [paint(spec.fill)];
  else if (spec.fills) node.fills = spec.fills.map(paint);
  if (spec.fillAlpha !== undefined && node.fills[0]) {
    node.fills = [{ ...node.fills[0], opacity: spec.fillAlpha }];
  }
}

function applyStrokes(node, spec) {
  if (spec.stroke) {
    node.strokes = [paint(spec.stroke)];
    node.strokeWeight = spec.strokeWeight ?? 1;
  }
  if (spec.dashPattern) node.dashPattern = spec.dashPattern;
}

function applyCorner(node, spec) {
  if (spec.cornerRadius !== undefined) node.cornerRadius = spec.cornerRadius;
  if (spec.topLeftRadius) node.topLeftRadius = spec.topLeftRadius;
  if (spec.topRightRadius) node.topRightRadius = spec.topRightRadius;
  if (spec.bottomLeftRadius) node.bottomLeftRadius = spec.bottomLeftRadius;
  if (spec.bottomRightRadius) node.bottomRightRadius = spec.bottomRightRadius;
}

function positionNode(node, spec) {
  node.x = spec.x ?? 0;
  node.y = spec.y ?? 0;
  if (spec.width && node.type !== "TEXT") node.resize(spec.width, node.height);
}

async function placeImage(spec) {
  const frame = figma.createFrame();
  frame.name = spec.name || "image";
  frame.x = spec.x ?? 0;
  frame.y = spec.y ?? 0;
  frame.resize(spec.width ?? 300, spec.height ?? 200);
  frame.clipsContent = true;
  frame.fills = [paint(spec.placeholder || "#E8E0F0")];
  if (spec.radius !== undefined) frame.cornerRadius = spec.radius;

  if (spec.imageBytes) {
    try {
      const bytes = base64ToBytes(spec.imageBytes);
      if (!bytes) throw new Error("base64 inválida");
      const image = figma.createImage(bytes);
      frame.fills = [{ type: "IMAGE", imageHash: image.hash, scaleMode: "FILL" }];
    } catch (err) {
      figma.notify(`⚠️ ${spec.src || spec.name}: ${err.message}`);
    }
  } else {
    const label = figma.createText();
    await figma.loadFontAsync({ family: "Inter", style: "Regular" });
    label.characters = `[image: ${spec.src || spec.name || "add asset"}]`;
    label.fontName = { family: "Inter", style: "Regular" };
    label.fontSize = 12;
    label.fills = [{ type: "SOLID", color: hexToRGB("#666666") }];
    label.x = 12;
    label.y = 10;
    frame.appendChild(label);
  }
  return frame;
}

async function buildFrame(spec, parent) {
  const node = figma.createFrame();

  node.name = spec.name || "frame";
  node.x = spec.x ?? 0;
  node.y = spec.y ?? 0;
  node.resize(spec.width ?? 0, spec.height ?? 0);
  node.clipsContent = spec.clip ?? false;

  applyFills(node, spec);
  applyStrokes(node, spec);
  applyCorner(node, spec);

  if (spec.opacity !== undefined) node.opacity = spec.opacity;

  if (spec.effectShadow) {
    node.effects = [
      {
        type: "DROP_SHADOW",
        color: hexToRGB(spec.effectShadow.color || "#000000", spec.effectShadow.alpha ?? 0.1),
        offset: spec.effectShadow.offset || { x: 0, y: 10 },
        radius: spec.effectShadow.radius || 25,
        spread: spec.effectShadow.spread || 0,
        visible: true,
        blendMode: "NORMAL",
      },
    ];
  }

  if (spec.layoutMode) {
    node.layoutMode = spec.layoutMode;
    if (spec.itemSpacing !== undefined) node.itemSpacing = spec.itemSpacing;
    if (spec.padding !== undefined) {
      node.paddingLeft = spec.padding;
      node.paddingRight = spec.padding;
      node.paddingTop = spec.padding;
      node.paddingBottom = spec.padding;
    }
    if (spec.primaryAxisAlignItems) node.primaryAxisAlignItems = spec.primaryAxisAlignItems;
    if (spec.counterAxisAlignItems) node.counterAxisAlignItems = spec.counterAxisAlignItems;
  }

  if (spec.elements && Array.isArray(spec.elements)) {
    for (const childSpec of spec.elements) {
      const child = await buildElement(childSpec, node);
      if (child) {
        node.appendChild(child);
        if (!node.layoutMode) positionNode(child, childSpec);
      }
    }
  }

  if (parent) parent.appendChild(node);
  return node;
}

async function buildText(spec, parent) {
  const node = figma.createText();
  node.name = spec.name || "text";
  node.characters = spec.characters ?? spec.content ?? "";

  const family = spec.fontFamily || "Space Grotesk";
  const weight = spec.fontWeight || 400;
  const fontName = await ensureFont(family, weight);
  node.fontName = fontName;
  node.fontSize = spec.fontSize ?? 16;

  if (spec.letterSpacing !== undefined) node.letterSpacing = spec.letterSpacing;
  if (spec.lineHeight !== undefined) {
    const v = spec.lineHeight;
    node.lineHeight = v > 3 ? { value: v, unit: "PIXELS" } : { value: Math.round(v * 100), unit: "PERCENT" };
  }
  if (spec.textCase === "UPPER") node.textCase = "UPPER";
  if (spec.textAlignHorizontal) node.textAlignHorizontal = spec.textAlignHorizontal;
  if (spec.textAutoResize) node.textAutoResize = spec.textAutoResize;

  node.x = spec.x ?? 0;
  node.y = spec.y ?? 0;
  if (spec.width) node.resize(spec.width, node.height);

  applyFills(node, spec);

  if (parent) parent.appendChild(node);
  return node;
}

async function buildRect(spec, parent) {
  const node = figma.createRectangle();
  node.name = spec.name || "rect";
  node.x = spec.x ?? 0;
  node.y = spec.y ?? 0;
  node.resize(spec.width ?? 0, spec.height ?? 0);
  applyFills(node, spec);
  applyStrokes(node, spec);
  applyCorner(node, spec);
  if (spec.rotation) node.rotation = spec.rotation;
  if (spec.opacity !== undefined) node.opacity = spec.opacity;
  if (parent) parent.appendChild(node);
  return node;
}

async function buildEllipse(spec, parent) {
  const node = figma.createEllipse();
  node.name = spec.name || "ellipse";
  node.x = spec.x ?? 0;
  node.y = spec.y ?? 0;
  node.resize(spec.width ?? 0, spec.height ?? 0);
  applyFills(node, spec);
  applyStrokes(node, spec);
  if (spec.opacity !== undefined) node.opacity = spec.opacity;
  if (parent) parent.appendChild(node);
  return node;
}

async function buildLine(spec, parent) {
  const node = figma.createLine();
  node.name = spec.name || "line";
  node.x = spec.x ?? 0;
  node.y = spec.y ?? 0;
  node.resize(spec.width ?? 0, 0);
  applyStrokes(node, spec);
  if (spec.rotation) node.rotation = spec.rotation;
  if (parent) parent.appendChild(node);
  return node;
}

async function buildElement(spec, parent) {
  switch (spec.type) {
    case "frame": return buildFrame(spec, parent);
    case "text": return buildText(spec, parent);
    case "rect": return buildRect(spec, parent);
    case "ellipse": return buildEllipse(spec, parent);
    case "line": return buildLine(spec, parent);
    case "image": return placeImage(spec);
    default: return null;
  }
}

async function renderScreen(spec) {
  const tag = `PS:${spec.name}`;

  const existing = figma.currentPage.findAll((n) => n.name === tag);
  existing.forEach((n) => n.remove());

  const frame = figma.createFrame();
  frame.name = tag;
  frame.x = spec.x ?? 0;
  frame.y = spec.y ?? 0;
  frame.resize(spec.width ?? 1440, spec.height ?? 900);
  frame.clipsContent = true;
  if (spec.background) frame.fills = [paint(spec.background)];

  for (const el of spec.elements || []) {
    try {
      const child = await buildElement(el, frame);
      if (child) {
        frame.appendChild(child);
        if (!frame.layoutMode) positionNode(child, el);
      }
    } catch (err) {
      console.warn(`elemento "${el.name}" en PS:${spec.name}: ${err.message}`);
    }
  }

  figma.currentPage.appendChild(frame);
  return tag;
}

async function main() {
  const tags = [];
  const errors = [];
  for (const spec of SPECS) {
    try {
      const tag = await renderScreen(spec);
      tags.push(tag);
    } catch (err) {
      errors.push(`PS:${spec.name}: ${err.message}`);
      console.error(`screen ${spec.name}`, err);
    }
    await new Promise((r) => setTimeout(r, 30));
  }
  const sel = tags.map((t) => figma.currentPage.findOne((n) => n.name === t)).filter(Boolean);
  if (sel.length) {
    figma.currentPage.selection = sel;
    figma.viewport.scrollAndZoomIntoView(sel);
  }
  if (errors.length) {
    figma.notify(`⚠️ Done ${tags.length}/${SPECS.length}. Errores:\n${errors.join("\n")}`);
  } else {
    figma.notify(`Portfolio Sync: ${tags.length} pantalla(s) dibujadas ✅`);
  }
  figma.closePlugin();
}

main().catch((err) => {
  figma.notify(`❌ Error: ${err.message}`);
  console.error(err);
  figma.closePlugin();
});